<?php

declare(strict_types=1);namespace backend\controllers;use backend\components\AdminController;use common\models\{User,UserPermission};use common\services\{AuditService,SessionTracker};use Yii;use yii\data\ActiveDataProvider;use yii\web\NotFoundHttpException;
final class UserController extends AdminController { protected string $permission='manageUsers'; public function actionIndex():string{$q=User::find()->orderBy(['id'=>SORT_DESC]);$s=trim((string)Yii::$app->request->get('q'));if($s!=='')$q->andWhere(['or',['like','username',$s],['like','email',$s],['uuid'=>$s]]);return $this->render('index',['dataProvider'=>new ActiveDataProvider(['query'=>$q,'pagination'=>['pageSize'=>30]]),'q'=>$s]);}public function actionView(int $id):string{$m=$this->find($id);return $this->render('view',['model'=>$m,'roles'=>Yii::$app->authManager->getRolesByUser($id),'launcherPermissions'=>UserPermission::find()->where(['uuid'=>$m->uuid])->orderBy('name')->all()]);}public function actionStatus(int $id,string $status){if(!Yii::$app->request->isPost)throw new \yii\web\MethodNotAllowedHttpException();$m=$this->find($id);if(!in_array($status,[User::STATUS_ACTIVE,User::STATUS_PENDING,User::STATUS_BLOCKED],true))throw new \yii\web\BadRequestHttpException();$m->status=$status;if($status===User::STATUS_BLOCKED){$m->accessToken=null;$m->serverID=null;(new SessionTracker())->revokeAll($id);} $m->save(false,['status','accessToken','serverID']);AuditService::log('admin.user.status','user',(string)$id,['status'=>$status]);return $this->redirect(['view','id'=>$id]);}public function actionAddLauncherPermission(int $id){if(!Yii::$app->request->isPost)throw new \yii\web\MethodNotAllowedHttpException();$u=$this->find($id);$name=trim((string)Yii::$app->request->post('permission'));if($name!==''&&strlen($name)<=100){$p=new UserPermission(['uuid'=>$u->uuid,'name'=>$name]);$p->save();AuditService::log('admin.launcher.permission.add','user',(string)$id,['permission'=>$name]);}return $this->redirect(['view','id'=>$id]);}public function actionDeleteLauncherPermission(int $id,string $name){if(!Yii::$app->request->isPost)throw new \yii\web\MethodNotAllowedHttpException();$u=$this->find($id);UserPermission::deleteAll(['uuid'=>$u->uuid,'name'=>$name]);AuditService::log('admin.launcher.permission.delete','user',(string)$id,['permission'=>$name]);return $this->redirect(['view','id'=>$id]);}public function actionRole(int $id,string $role){if(!Yii::$app->request->isPost)throw new \yii\web\MethodNotAllowedHttpException();$am=Yii::$app->authManager;if(!in_array($role,['admin','moderator','user'],true)||!($r=$am->getRole($role)))throw new \yii\web\BadRequestHttpException();foreach($am->getRolesByUser($id) as $old)$am->revoke($old,$id);$am->assign($r,$id);AuditService::log('admin.user.role','user',(string)$id,['role'=>$role]);return $this->redirect(['view','id'=>$id]);}private function find(int $id):User{$m=User::findOne($id);if(!$m)throw new NotFoundHttpException();return $m;}}
